#!/data/data/com.termux/files/usr/bin/bash
# apply_all38.sh - التاريخ والجغرافيا للأولى ثانوي: الجزء 1 = 24 بطاقة تاريخ + 19 بطاقة جغرافيا + الخرائط الذهنية (زر 🗺️)
# لا يمسّ مفتاح الترخيص: يضيف ملفات جديدة ووسوم script فقط في index.html بعد نسخة احتياطية.
cd ~/zad-1am/www 2>/dev/null || cd "$(dirname "$0")/www" || { echo "لم أجد مجلد www"; exit 1; }
[ -f index.html.bak_hg1 ] || cp index.html index.html.bak_hg1

# --- اكتشاف مفاتيح مادتي التاريخ والجغرافيا في الأولى ثانوي (كل الشعب) من db.js ---
CH=$(tr -d '\n' < db.js | sed 's/"AS1": *{"name"/\n&/' | tail -1 | sed 's/"AS2": *{"name".*//')
KH=$(printf '%s' "$CH" | grep -o '"key": *"[^"]*", *"name": *"[^"]*التاريخ[^"]*"' | sed 's/"key": *"\([^"]*\)".*/\1/' | sort -u)
KG=$(printf '%s' "$CH" | grep -o '"key": *"[^"]*", *"name": *"[^"]*الجغرافيا[^"]*"' | sed 's/"key": *"\([^"]*\)".*/\1/' | sort -u)
if [ -z "$KH" ] && [ -z "$KG" ]; then
  printf '%s' "$CH" | head -c 4000 > ~/storage/downloads/hg1_diag.txt
  echo "لم أجد مادتي التاريخ/الجغرافيا للأولى ثانوي في db.js. كتبتُ تشخيصا في التنزيلات: hg1_diag.txt - أرسله لي."
  echo "لم يُغيَّر شيء."
  exit 1
fi
JH=$(printf '%s\n' $KH | sed 's/.*/"&"/' | paste -sd, | sed 's/^/[/;s/$/]/'); [ -z "$KH" ] && JH='[]'
JG=$(printf '%s\n' $KG | sed 's/.*/"&"/' | paste -sd, | sed 's/^/[/;s/$/]/'); [ -z "$KG" ] && JG='[]'
echo "مفاتيح التاريخ: $JH"
echo "مفاتيح الجغرافيا: $JG"

cat > hg1_data.js <<'ZAD_EOF'
